# ini_unquote <value>
# Drop surrounding whitespace and one layer of matching quotes.
ini_unquote() {
  local v="${1:-}"
  v="${v#"${v%%[![:space:]]*}"}"
  v="${v%"${v##*[![:space:]]}"}"
  if [[ ${#v} -ge 2 && ( "$v" == \"*\" || "$v" == \'*\' ) ]]; then
    v="${v:1:${#v}-2}"
  fi
  printf '%s' "$v"
}

# ini_get <file> <group> <key>
# Print the first value of <key> inside <group>, unquoted.  Keys in other
# groups are ignored; missing files or keys print nothing.
ini_get() {
  local file="$1" group="$2" key="$3" raw
  [[ -f "$file" ]] || return 0
  file="$(readlink -f -- "$file" 2>/dev/null || printf '%s' "$file")"
  raw="$(awk -v group="$group" -v key="$key" '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
    /^[ \t]*\[/ {
      line = trim($0)
      current = substr(line, 2, length(line) - 2)
      next
    }
    current == group {
      pos = index($0, "=")
      if (pos > 0 && trim(substr($0, 1, pos - 1)) == key) {
        print trim(substr($0, pos + 1))
        exit
      }
    }
  ' "$file")"
  ini_unquote "$raw"
}

# ini_set <file> <group> <key> <value>
# Replace the key inside <group>, insert it after the group header, or append a
# new group.  Duplicate keys in the same group collapse to one.
ini_set() {
  local file="$1" group="$2" key="$3" value="$4" real tmp
  mkdir -p -- "$(dirname -- "$file")"
  [[ -f "$file" ]] || : > "$file"
  real="$(readlink -f -- "$file" 2>/dev/null || printf '%s' "$file")"
  tmp="$(mktemp "${real}.XXXXXX")" || return 1

  if awk -v group="$group" -v key="$key" -v value="$value" '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
    /^[ \t]*\[/ {
      line = trim($0)
      if (in_group && !done) { print key "=" value; done = 1 }
      in_group = (substr(line, 2, length(line) - 2) == group)
      if (in_group) seen_group = 1
      print
      next
    }
    {
      if (in_group) {
        pos = index($0, "=")
        if (pos > 0 && trim(substr($0, 1, pos - 1)) == key) {
          if (!done) { print key "=" value; done = 1 }
          next
        }
      }
