# ini_unset <file> <group> <key>
# Remove the key from <group>.  If that leaves the group with no content, drop
# the group header too, so an undo does not leave empty scaffolding behind.
ini_unset() {
  local file="$1" group="$2" key="$3" real tmp
  [[ -f "$file" ]] || return 0
  real="$(readlink -f -- "$file" 2>/dev/null || printf '%s' "$file")"
